<template><div class="spotlight-home min-h-screen bg-[#f4f1ea] text-stone-900"><section class="mx-auto grid max-w-6xl gap-6 px-4 py-7 sm:py-10 md:grid-cols-[1.2fr_.8fr] md:py-20"><div class="flex flex-col justify-center"><p class="text-sm font-bold uppercase tracking-[.3em] text-violet-700">{{ t('home.featured.title') }}</p><h1 class="mt-4 text-4xl font-black leading-none sm:text-5xl md:text-7xl">{{ featured ? getLocalizedText(featured.title) : t('home.featured.description') }}</h1><p class="mt-5 max-w-md text-base text-stone-600 sm:mt-6 sm:text-lg">{{ featured ? getLocalizedText(featured.description) : t('home.latest.description') }}</p><RouterLink v-if="featured" :to="`/products/${featured.slug}`" class="mt-7 inline-flex h-12 w-fit items-center rounded-full bg-stone-900 px-7 text-sm font-bold text-white">{{ t('home.featured.viewAll') }}</RouterLink></div><div class="relative mx-auto aspect-[4/5] w-full max-w-sm overflow-hidden rounded-2xl bg-stone-300 md:max-w-none md:rounded-[2rem]"><img v-if="featured?.cover" :src="featured.cover" :alt="getLocalizedText(featured.title)" class="h-full w-full object-cover"/><div v-else class="grid h-full place-items-center text-stone-500">{{ t('home.featured.empty') }}</div><span class="absolute left-5 top-5 rounded-full bg-white/85 px-3 py-1 text-xs font-bold">01</span></div></section><section class="mx-auto max-w-6xl px-4 pb-16"><div class="mb-5 flex items-center justify-between gap-4"><h2 class="text-2xl font-black">{{ t('home.latest.title') }}</h2><RouterLink to="/products" class="shrink-0 text-sm font-bold text-violet-700">{{ t('home.featured.viewAll') }}</RouterLink></div><TemplateProductCollection :products="products.slice(1)" :mode="templateMode" grid-class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4" @click="go" @quick-buy="quickBuy" /></section><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { productAPI } from '../../api'; import { useLocalized } from '../../composables/useProduct'; import { useAppStore } from '../../stores/app'; import TemplateProductCollection from '../components/TemplateProductCollection.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const {getLocalizedText}=useLocalized(); const router=useRouter(); const app=useAppStore(); const products=ref<any[]>([]); const selected=ref<any>(null); const quickVisible=ref(false); const featured=computed(()=>products.value[0]); const templateMode=computed<'card'|'list'>(()=>app.config?.template_mode==='list'?'list':'card'); const go=(s:string)=>router.push(`/products/${s}`); const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true}; onMounted(async()=>{await app.loadConfig();const r=await productAPI.list({page:1,page_size:9});products.value=r.data.data||[]})</script>
